    /**
     * Method to retrieve the Seller via SellerFetchOneSummary
     * @param 	summary SellerFetchOneSummary 
     * @return 	SellerFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Seller getSeller( SellerFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "SellerFetchOneSummary arg cannot be null" );
    	
    	Seller entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Seller
        	// --------------------------------------
        	CompletableFuture<Seller> futureEntity = queryGateway.query(new FindSellerQuery( new LoadSellerFilter( summary.getSellerId() ) ), ResponseTypes.instanceOf(Seller.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Seller with id " + summary.getSellerId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


